const lead = $input.first().json;

const CONFIG = {
  COMPANY_NAME: 'Valfin Tech',
  OWNER_PHONE: '+18575261499',
  OWNER_EMAIL: 'valfintechnologies@gmail.com',
  TWILIO_FROM_NUMBER: '+18889839308',
  EMAIL_ALERTS_ENABLED: true,
  SMS_ALERTS_ENABLED: false,
  DEFAULT_TIMEZONE: 'America/New_York'
};

const name = [lead.firstName, lead.lastName].filter(Boolean).join(' ') || 'Unknown';
const firstName = lead.firstName || 'there';
const phone = lead.phone || 'Not provided';
const email = lead.email || 'Not provided';
const service = lead.serviceNeeded || 'Not specified';
const address = lead.address || 'Not provided';
const preferredTime = lead.preferredTime || 'Not specified';
const source = lead.source || 'Unknown';
const leadId = lead.leadId || '';

let submitted = 'Just now';
if (lead.dateCreated) {
  try {
    submitted = DateTime.fromISO(lead.dateCreated).setZone(CONFIG.DEFAULT_TIMEZONE).toFormat("MMM d, yyyy 'at' h:mm a ZZZZ");
  } catch (e) { submitted = lead.dateCreated; }
}

const smsMessage = 'New lead: ' + name + ' (' + service + ')\nPhone: ' + phone + (leadId ? '\n' + leadId : '');

const emailSubject = CONFIG.COMPANY_NAME + ' - New Lead: ' + name + ' (' + service + ')';

const rows = [
  ['Name', name],
  ['Phone', phone],
  ['Email', email],
  ['Address', address],
  ['Service Requested', service],
  ['Preferred Time', preferredTime],
  ['Lead Source', source],
  ['Submitted', submitted]
];
if (leadId) rows.push(['Lead ID', leadId]);

const rowsHtml = rows.map(([label, value]) =>
  '<tr><td style="padding:6px 12px 6px 0;font-weight:bold;color:#374151;white-space:nowrap;">' + label + '</td><td style="padding:6px 0;color:#111827;">' + value + '</td></tr>'
).join('');

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;">' +
  '<h2 style="color:#111827;border-bottom:2px solid #e5e7eb;padding-bottom:8px;">New Lead Received</h2>' +
  '<table style="width:100%;border-collapse:collapse;margin-top:12px;">' + rowsHtml + '</table>' +
  '<p style="margin-top:20px;"><a href="tel:' + phone + '" style="background:#111827;color:#ffffff;padding:10px 18px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block;">Call ' + firstName + '</a></p>' +
  '<p style="color:#6b7280;font-size:12px;margin-top:24px;">Sent automatically by ' + CONFIG.COMPANY_NAME + '.</p>' +
  '</div>';

return [{ json: {
  ...lead,
  emailEnabled: CONFIG.EMAIL_ALERTS_ENABLED,
  smsEnabled: CONFIG.SMS_ALERTS_ENABLED,
  ownerEmail: CONFIG.OWNER_EMAIL,
  ownerPhone: CONFIG.OWNER_PHONE,
  twilioFrom: CONFIG.TWILIO_FROM_NUMBER,
  emailSubject,
  emailHtml,
  smsMessage
}}];
